//! The C ABI (`include/bridgey_core.h`, generated by cbindgen and checked by a test).
//!
//! Conventions, as in the Connect anywhere core (rust/core/src/ffi.rs):
//! - A client is a `uint64_t` handle, never a pointer: a call with a stopped or freed handle returns
//!   `BRIDGEY_ERR_STOPPED` instead of touching freed memory.
//! - Strings in are NUL-terminated UTF-8 the caller owns for the call. Strings and events out are owned by
//!   this library and freed with `bridgey_string_free` and `bridgey_event_free`.
//! - Events are pulled with `bridgey_next_event`, a blocking poll with a timeout, from one bounded queue.
//!   `bridgey_client_stop` wakes every poll.
//! - Storage callbacks may run on any of the library's threads, so they must be thread-safe.
//! - Panics never cross the boundary (`BRIDGEY_ERR_INTERNAL`).
//!
//! Media will not go through this event path: binary frames stay in buffers (docs/session-client.md).

use crate::client::{Client, ClientError, Config, ALLOW_DEFAULT, DEFAULT_PORT};
use crate::events::{Event, Next};
use crate::trust::{FileStorage, MemoryStorage, Storage};
use std::collections::HashMap;
use std::ffi::{c_char, c_void, CStr, CString};
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex, OnceLock};
use std::time::Duration;

/// The C ABI version this header describes; compare with bridgey_abi_version() at start-up.
pub const BRIDGEY_ABI_VERSION: u32 = 1;

pub const BRIDGEY_OK: i32 = 0;
pub const BRIDGEY_ERR_INVALID_ARGUMENT: i32 = -1;
pub const BRIDGEY_ERR_NOT_CONNECTED: i32 = -2;
pub const BRIDGEY_ERR_FEATURE_OFF: i32 = -3;
pub const BRIDGEY_ERR_TOO_LARGE: i32 = -4;
pub const BRIDGEY_ERR_UNKNOWN_DEVICE: i32 = -5;
pub const BRIDGEY_ERR_STOPPED: i32 = -6;
pub const BRIDGEY_ERR_STORAGE: i32 = -7;
pub const BRIDGEY_ERR_IO: i32 = -8;
pub const BRIDGEY_ERR_INTERNAL: i32 = -99;

/// The result of a send: the `status` of `ClipboardSent` and `PingResult` events.
#[repr(i32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BridgeySendStatus {
    Delivered = 0,
    /// The other device has the feature off.
    Rejected = 1,
    /// No answer in time (10 s for clipboard, 5 s for ping).
    TimedOut = 2,
    /// The connection ended first.
    Failed = 3,
}

/// What an event is. Fields not listed for a kind are empty.
#[repr(u32)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BridgeyEventKind {
    /// A device on the network. device_id (an unauthenticated hint, may be empty), name, text = host,
    /// extra = platform, status = port.
    DeviceFound = 1,
    /// device_id, text = host, status = port.
    DeviceLost = 2,
    /// A device asked to pair while pairing was not allowed. device_id, name.
    PairingRequest = 3,
    /// The other device has not allowed pairing yet; tries continue for two minutes. id = pairing, name.
    PairingWaiting = 4,
    /// Compare the code. id = pairing, device_id, name, text = the six digits.
    PairingCode = 5,
    /// id = pairing, device_id, name, status = 0 paired or 1 not paired, text = reason.
    PairingFinished = 6,
    /// device_id, name.
    Connected = 7,
    /// device_id, text = reason.
    Disconnected = 8,
    /// device_id, text = this device's switches (JSON object of booleans), extra = the device's own.
    Features = 9,
    /// device_id, text = the text (exact length in text.len), extra = HTML when the sender had it.
    Clipboard = 10,
    /// id = request, device_id, status = BridgeySendStatus.
    ClipboardSent = 11,
    /// device_id.
    Ping = 12,
    /// id = request, device_id, status = BridgeySendStatus.
    PingResult = 13,
    /// device_id, name, status = 1 trusted or 0 forgotten.
    TrustChanged = 14,
    /// Events were dropped because the queue was full. id = how many; refresh from bridgey_snapshot.
    EventsDropped = 15,
    /// text = what went wrong.
    Error = 16,
    /// A file is coming in. id = transfer, device_id, name = file name, extra = MIME type, total = size.
    FileIncoming = 17,
    /// id = transfer, device_id, status = 1 incoming or 0 outgoing, bytes, total. At most four a second.
    FileProgress = 18,
    /// id = transfer, device_id, name = the name it was saved under, status = 1 incoming or 0 outgoing,
    /// text = where it was saved (incoming), total = size.
    FileDone = 19,
    /// id = transfer, device_id, name, status = 1 incoming or 0 outgoing, text = reason (`BridgeyEvent` docs in
    /// docs/session-client.md).
    FileFailed = 20,
    /// A link to open or dismiss; never opened by the library. device_id, text = the link, status = 1 when the host
    /// opens it now (the device asked for that and Open links right away is on), 0 to offer Open and Dismiss.
    Link = 21,
    /// id = request, device_id, status = BridgeySendStatus, text = `opened` when the device opened it at once.
    LinkSent = 22,
    /// A connected device's battery. device_id, status = level 0 to 100, id = 1 charging or 0.
    Battery = 23,
    /// The device asks this one to ring (status 1) or stop (0). device_id.
    /// Call bridgey_find_stopped when the person stops the sound here.
    FindRequested = 24,
    /// The device says it is ringing (status 1) or has stopped (0), after bridgey_find. device_id.
    FindState = 25,
    /// A phone notification. device_id, status = 1 quiet (history only: no banner, no sound) or 0, text = JSON:
    /// packageName, applicationName, notificationId, title, text, timestamp, icon (base64 PNG), callType, actions
    /// ([{token, title, allowsReply}]), quiet, redacted, code ({code, service, channel} when one was found).
    Notification = 26,
    /// The phone's notification went away. device_id, text = notificationId, status = 1 when a call ended.
    NotificationRemoved = 27,
    /// Whether the phone shows Bridgey the text of code messages. device_id, text = allowed, hidden or not_linked.
    CodesStatus = 28,
    /// The phone asks for a Bluetooth LE advertisement of a service for 60 s (status 1; answer with
    /// bridgey_codes_advertise_result) or to stop it (status 0, id = 1 when the link was made). device_id,
    /// text = the service UUID.
    CodesAdvertise = 29,
    /// The phone's media control for this device's player. device_id, text = the request ID (pass it to
    /// bridgey_media_result), name = toggle, pause, next, previous, seek or volume, status = the value (seconds or 0 to
    /// 100), id = 1 when there is a value.
    MediaCommand = 30,
    /// Connect away from home. text = off, disabled, connecting, unreachable or online, extra = JSON array of the
    /// paired device IDs the control service says are online.
    ConnectState = 31,
}

/// Bytes owned by the library: UTF-8, NUL-terminated for convenience, `len` without the NUL. `ptr` is NULL when
/// there is no value.
#[repr(C)]
pub struct BridgeyStr {
    pub ptr: *const u8,
    pub len: usize,
}

#[repr(C)]
pub struct BridgeyEvent {
    pub kind: BridgeyEventKind,
    pub status: i32,
    pub id: u64,
    pub device_id: BridgeyStr,
    pub name: BridgeyStr,
    pub text: BridgeyStr,
    pub extra: BridgeyStr,
    /// File events: bytes so far.
    pub bytes: u64,
    /// File events: the file's size.
    pub total: u64,
}

#[repr(C)]
pub struct BridgeyConfig {
    /// sizeof(BridgeyConfig), so later versions can add fields.
    pub struct_size: u32,
    /// 0 uses Bridgey's port, 42458.
    pub port: u16,
    /// 1 accepts connections (needed to be paired with and reconnected to).
    pub listen: u8,
    /// 1 runs the built-in DNS-SD browsing and publishing.
    pub discovery: u8,
    /// The event queue's size; 0 uses 1024.
    pub event_capacity: u32,
    /// The name other devices show.
    pub device_name: *const c_char,
    /// `windows`, `linux`, `ios`.
    pub platform: *const c_char,
    /// Without storage callbacks: keep the identity and trusted devices in owner-only files here. Both NULL:
    /// in memory only (tests).
    pub data_dir: *const c_char,
    /// Read only when struct_size covers it (hosts built before it pass a smaller size). Where received files are
    /// saved; NULL refuses files. bridgey_set_receive_dir changes it later.
    pub receive_dir: *const c_char,
    /// 1: connect only to devices named with bridgey_connect, as a share extension does, instead of keeping every
    /// trusted device connected.
    pub manual_connect: u8,
}

/// The size of a BridgeyConfig from before receive_dir, which hosts may still pass.
const CONFIG_V1_SIZE: usize = std::mem::offset_of!(BridgeyConfig, receive_dir);

/// An opaque buffer a storage `load` callback copies a value into with `bridgey_buffer_set`.
pub struct BridgeyBuffer {
    data: Option<Vec<u8>>,
}

/// Storage the host provides (DPAPI or Credential Locker on Windows, the Keychain on iOS). Keys are short
/// ASCII names (`identity`, `trust`). Callbacks return 1 found (load), 0 done or not found, negative on error.
#[repr(C)]
pub struct BridgeyStorage {
    pub context: *mut c_void,
    pub load: Option<unsafe extern "C" fn(context: *mut c_void, key: *const c_char, out: *mut BridgeyBuffer) -> i32>,
    pub store: Option<unsafe extern "C" fn(context: *mut c_void, key: *const c_char, data: *const u8, len: usize) -> i32>,
    pub remove: Option<unsafe extern "C" fn(context: *mut c_void, key: *const c_char) -> i32>,
}

struct HostStorage {
    context: usize,
    load: unsafe extern "C" fn(*mut c_void, *const c_char, *mut BridgeyBuffer) -> i32,
    store: unsafe extern "C" fn(*mut c_void, *const c_char, *const u8, usize) -> i32,
    remove: unsafe extern "C" fn(*mut c_void, *const c_char) -> i32,
}

// SAFETY: the header requires storage callbacks to be callable from any thread with this context.
unsafe impl Send for HostStorage {}
unsafe impl Sync for HostStorage {}

impl Storage for HostStorage {
    fn load(&self, key: &str) -> Result<Option<Vec<u8>>, String> {
        let key = CString::new(key).map_err(|_| "key")?;
        let mut buffer = BridgeyBuffer { data: None };
        // SAFETY: the host's callback with its own context; `buffer` lives for the call.
        let rc = unsafe { (self.load)(self.context as *mut c_void, key.as_ptr(), &mut buffer) };
        match rc {
            1 => Ok(Some(buffer.data.unwrap_or_default())),
            0 => Ok(None),
            e => Err(format!("load failed ({e})")),
        }
    }

    fn store(&self, key: &str, value: &[u8]) -> Result<(), String> {
        let key = CString::new(key).map_err(|_| "key")?;
        // SAFETY: as above; `value` lives for the call.
        let rc = unsafe { (self.store)(self.context as *mut c_void, key.as_ptr(), value.as_ptr(), value.len()) };
        if rc >= 0 {
            Ok(())
        } else {
            Err(format!("store failed ({rc})"))
        }
    }

    fn remove(&self, key: &str) -> Result<(), String> {
        let key = CString::new(key).map_err(|_| "key")?;
        // SAFETY: as above.
        let rc = unsafe { (self.remove)(self.context as *mut c_void, key.as_ptr()) };
        if rc >= 0 {
            Ok(())
        } else {
            Err(format!("remove failed ({rc})"))
        }
    }
}

fn clients() -> &'static Mutex<HashMap<u64, Arc<Client>>> {
    static CLIENTS: OnceLock<Mutex<HashMap<u64, Arc<Client>>>> = OnceLock::new();
    CLIENTS.get_or_init(|| Mutex::new(HashMap::new()))
}

static NEXT_HANDLE: AtomicU64 = AtomicU64::new(1);

fn client(handle: u64) -> Option<Arc<Client>> {
    clients().lock().unwrap().get(&handle).cloned()
}

fn code(e: ClientError) -> i32 {
    match e {
        ClientError::InvalidArgument(_) => BRIDGEY_ERR_INVALID_ARGUMENT,
        ClientError::NotConnected => BRIDGEY_ERR_NOT_CONNECTED,
        ClientError::FeatureOff => BRIDGEY_ERR_FEATURE_OFF,
        ClientError::TooLarge => BRIDGEY_ERR_TOO_LARGE,
        ClientError::UnknownDevice => BRIDGEY_ERR_UNKNOWN_DEVICE,
        ClientError::Stopped => BRIDGEY_ERR_STOPPED,
        ClientError::Storage(_) => BRIDGEY_ERR_STORAGE,
        ClientError::Io(_) => BRIDGEY_ERR_IO,
    }
}

fn guard(f: impl FnOnce() -> i32) -> i32 {
    std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)).unwrap_or(BRIDGEY_ERR_INTERNAL)
}

/// A string argument: None when NULL; Err when not UTF-8.
///
/// # Safety
/// `ptr` is NULL or a NUL-terminated string valid for the call.
unsafe fn arg<'a>(ptr: *const c_char) -> Result<Option<&'a str>, i32> {
    if ptr.is_null() {
        return Ok(None);
    }
    CStr::from_ptr(ptr).to_str().map(Some).map_err(|_| BRIDGEY_ERR_INVALID_ARGUMENT)
}

fn owned(text: Option<String>) -> BridgeyStr {
    match text {
        None => BridgeyStr { ptr: std::ptr::null(), len: 0 },
        Some(t) => {
            let len = t.len();
            let mut bytes = t.into_bytes();
            bytes.push(0);
            let boxed = bytes.into_boxed_slice();
            BridgeyStr { ptr: Box::into_raw(boxed) as *const u8, len }
        }
    }
}

/// # Safety
/// `s` came from `owned` and is freed once.
unsafe fn free_owned(s: &BridgeyStr) {
    if !s.ptr.is_null() {
        drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(s.ptr as *mut u8, s.len + 1)));
    }
}

fn to_c(event: Event) -> BridgeyEvent {
    use BridgeyEventKind as K;
    let s = |v: &str| Some(v.to_string());
    let (mut bytes, mut total) = (0u64, 0u64);
    let (kind, status, id, device_id, name, text, extra) = match event {
        Event::Found { device_id, name, platform, host, port } => (K::DeviceFound, i32::from(port), 0, device_id, s(&name), Some(host), platform),
        Event::Lost { device_id, host, port } => (K::DeviceLost, i32::from(port), 0, device_id, None, Some(host), None),
        Event::PairingRequest { device_id, name } => (K::PairingRequest, 0, 0, Some(device_id), Some(name), None, None),
        Event::PairingWaiting { pairing, name } => (K::PairingWaiting, 0, pairing, None, Some(name), None, None),
        Event::PairingCode { pairing, device_id, name, code } => (K::PairingCode, 0, pairing, Some(device_id), Some(name), Some(code), None),
        Event::PairingFinished { pairing, device_id, name, ok, reason } => (K::PairingFinished, i32::from(!ok), pairing, device_id, name, Some(reason), None),
        Event::Connected { device_id, name } => (K::Connected, 0, 0, Some(device_id), Some(name), None, None),
        Event::Disconnected { device_id, reason } => (K::Disconnected, 0, 0, Some(device_id), None, Some(reason), None),
        Event::Features { device_id, local, remote } => (K::Features, 0, 0, Some(device_id), None, Some(local.to_json().to_string()), Some(remote.to_json().to_string())),
        Event::Clipboard { device_id, text, html } => (K::Clipboard, 0, 0, Some(device_id), None, Some(text), html),
        Event::ClipboardSent { request, device_id, status } => (K::ClipboardSent, status as i32, request, Some(device_id), None, None, None),
        Event::Ping { device_id } => (K::Ping, 0, 0, Some(device_id), None, None, None),
        Event::PingResult { request, device_id, status } => (K::PingResult, status as i32, request, Some(device_id), None, None, None),
        Event::TrustChanged { device_id, name, trusted } => (K::TrustChanged, i32::from(trusted), 0, Some(device_id), Some(name), None, None),
        Event::Dropped { count } => (K::EventsDropped, 0, count, None, None, None, None),
        Event::Error { text } => (K::Error, 0, 0, None, None, Some(text), None),
        Event::FileIncoming { transfer, device_id, name, size, mime } => {
            total = size;
            (K::FileIncoming, 1, transfer, Some(device_id), Some(name), None, Some(mime))
        }
        Event::FileProgress { transfer, device_id, incoming, bytes: b, total: t } => {
            (bytes, total) = (b, t);
            (K::FileProgress, i32::from(incoming), transfer, Some(device_id), None, None, None)
        }
        Event::FileDone { transfer, device_id, incoming, name, path, size } => {
            (bytes, total) = (size, size);
            (K::FileDone, i32::from(incoming), transfer, Some(device_id), Some(name), path, None)
        }
        Event::FileFailed { transfer, device_id, incoming, name, reason } => (K::FileFailed, i32::from(incoming), transfer, Some(device_id), Some(name), Some(reason), None),
        Event::Link { device_id, url, open } => (K::Link, i32::from(open), 0, Some(device_id), None, Some(url), None),
        Event::LinkSent { request, device_id, status, opened } => (K::LinkSent, status as i32, request, Some(device_id), None, opened.then(|| "opened".to_string()), None),
        Event::Battery { device_id, level, charging } => (K::Battery, i32::from(level), u64::from(charging), Some(device_id), None, None, None),
        Event::FindRequested { device_id, ring } => (K::FindRequested, i32::from(ring), 0, Some(device_id), None, None, None),
        Event::FindState { device_id, ringing } => (K::FindState, i32::from(ringing), 0, Some(device_id), None, None, None),
        Event::Notification { device_id, notification } => (K::Notification, i32::from(notification.quiet), 0, Some(device_id), Some(notification.application_name.clone()), Some(notification.to_json().to_string()), None),
        Event::NotificationRemoved { device_id, notification_id, call_ended } => (K::NotificationRemoved, i32::from(call_ended), 0, Some(device_id), None, Some(notification_id), None),
        Event::CodesStatus { device_id, status } => (K::CodesStatus, 0, 0, Some(device_id), None, Some(status), None),
        Event::CodesAdvertise { device_id, service_uuid, start, linked } => (K::CodesAdvertise, i32::from(start), u64::from(linked), Some(device_id), None, Some(service_uuid), None),
        Event::ConnectState { state, online } => (K::ConnectState, 0, 0, None, None, Some(state), Some(serde_json::Value::from(online).to_string())),
        Event::MediaCommand { device_id, request_id, action, value } => (K::MediaCommand, value.unwrap_or(0) as i32, u64::from(value.is_some()), Some(device_id), Some(action), Some(request_id), None),
    };
    BridgeyEvent { kind, status, id, device_id: owned(device_id), name: owned(name), text: owned(text), extra: owned(extra), bytes, total }
}

/// The C ABI version (`BRIDGEY_ABI_VERSION` in the header).
#[no_mangle]
pub extern "C" fn bridgey_abi_version() -> u32 {
    BRIDGEY_ABI_VERSION
}

/// The library's version, a static string (do not free).
#[no_mangle]
pub extern "C" fn bridgey_version() -> *const c_char {
    concat!(env!("CARGO_PKG_VERSION"), "\0").as_ptr() as *const c_char
}

/// Starts a client: loads or creates this device's identity, loads its trusted devices, listens, discovers and
/// reconnects. `storage` may be NULL (then `config.data_dir`, or memory). On success `*out` is the handle.
///
/// # Safety
/// `config` points to a valid `BridgeyConfig`; `storage` is NULL or valid with callbacks that outlive the client;
/// `out` is valid for writing.
#[no_mangle]
pub unsafe extern "C" fn bridgey_client_new(config: *const BridgeyConfig, storage: *const BridgeyStorage, out: *mut u64) -> i32 {
    guard(|| {
        if config.is_null() || out.is_null() {
            return BRIDGEY_ERR_INVALID_ARGUMENT;
        }
        let c = &*config;
        let size = c.struct_size as usize;
        if size < CONFIG_V1_SIZE {
            return BRIDGEY_ERR_INVALID_ARGUMENT;
        }
        let (Ok(Some(name)), Ok(Some(platform)), Ok(data_dir)) = (arg(c.device_name), arg(c.platform), arg(c.data_dir)) else {
            return BRIDGEY_ERR_INVALID_ARGUMENT;
        };
        // Fields after data_dir only when the host's struct has them.
        let full = size >= std::mem::size_of::<BridgeyConfig>();
        let Ok(receive_dir) = (if full { arg(c.receive_dir) } else { Ok(None) }) else { return BRIDGEY_ERR_INVALID_ARGUMENT };
        let manual_connect = full && c.manual_connect != 0;
        let store: Arc<dyn Storage> = if !storage.is_null() {
            let s = &*storage;
            let (Some(load), Some(store), Some(remove)) = (s.load, s.store, s.remove) else { return BRIDGEY_ERR_INVALID_ARGUMENT };
            Arc::new(HostStorage { context: s.context as usize, load, store, remove })
        } else if let Some(dir) = data_dir {
            match FileStorage::new(dir) {
                Ok(f) => Arc::new(f),
                Err(_) => return BRIDGEY_ERR_STORAGE,
            }
        } else {
            Arc::new(MemoryStorage::default())
        };
        let mut config = Config::new(name, platform);
        config.port = if c.port == 0 { DEFAULT_PORT } else { c.port };
        config.listen = c.listen != 0;
        config.discovery = c.discovery != 0;
        if c.event_capacity > 0 {
            config.event_capacity = c.event_capacity as usize;
        }
        config.receive_dir = receive_dir.map(std::path::PathBuf::from);
        config.manual_connect = manual_connect;
        match Client::start(config, store) {
            Ok(client) => {
                let handle = NEXT_HANDLE.fetch_add(1, Ordering::Relaxed);
                clients().lock().unwrap().insert(handle, Arc::new(client));
                *out = handle;
                BRIDGEY_OK
            }
            Err(e) => code(e),
        }
    })
}

/// Stops listening, discovery and every session, and wakes every `bridgey_next_event`. The handle stays valid
/// for `bridgey_client_free`; other calls return `BRIDGEY_ERR_STOPPED`.
#[no_mangle]
pub extern "C" fn bridgey_client_stop(handle: u64) -> i32 {
    guard(|| match client(handle) {
        Some(c) => {
            c.stop();
            BRIDGEY_OK
        }
        None => BRIDGEY_ERR_STOPPED,
    })
}

/// Stops (if needed) and releases the client. The handle is invalid afterwards.
#[no_mangle]
pub extern "C" fn bridgey_client_free(handle: u64) {
    let _ = std::panic::catch_unwind(|| {
        let c = clients().lock().unwrap().remove(&handle);
        if let Some(c) = c {
            c.stop();
        }
    });
}

/// Waits up to `timeout_ms` for the next event. Returns 1 with `*out` set (free it with `bridgey_event_free`),
/// 0 after the timeout, or `BRIDGEY_ERR_STOPPED` once the client is stopped.
///
/// # Safety
/// `out` is valid for writing.
#[no_mangle]
pub unsafe extern "C" fn bridgey_next_event(handle: u64, timeout_ms: u32, out: *mut *mut BridgeyEvent) -> i32 {
    guard(|| {
        if out.is_null() {
            return BRIDGEY_ERR_INVALID_ARGUMENT;
        }
        *out = std::ptr::null_mut();
        let Some(c) = client(handle) else { return BRIDGEY_ERR_STOPPED };
        match c.next_event(Duration::from_millis(u64::from(timeout_ms))) {
            Next::Event(e) => {
                *out = Box::into_raw(Box::new(to_c(e)));
                1
            }
            Next::Timeout => 0,
            Next::Closed => BRIDGEY_ERR_STOPPED,
        }
    })
}

/// Frees an event from `bridgey_next_event`. NULL is ignored.
///
/// # Safety
/// `event` came from `bridgey_next_event` and is freed once.
#[no_mangle]
pub unsafe extern "C" fn bridgey_event_free(event: *mut BridgeyEvent) {
    if event.is_null() {
        return;
    }
    let e = Box::from_raw(event);
    free_owned(&e.device_id);
    free_owned(&e.name);
    free_owned(&e.text);
    free_owned(&e.extra);
}

/// Frees a string this library returned. NULL is ignored.
///
/// # Safety
/// `text` came from this library and is freed once.
#[no_mangle]
pub unsafe extern "C" fn bridgey_string_free(text: *mut c_char) {
    if !text.is_null() {
        drop(CString::from_raw(text));
    }
}

fn give(text: String) -> *mut c_char {
    CString::new(text).map(CString::into_raw).unwrap_or(std::ptr::null_mut())
}

/// This device's ID (free with `bridgey_string_free`), or NULL for a stopped handle.
#[no_mangle]
pub extern "C" fn bridgey_device_id(handle: u64) -> *mut c_char {
    std::panic::catch_unwind(|| client(handle).map(|c| give(c.device_id().to_string())).unwrap_or(std::ptr::null_mut())).unwrap_or(std::ptr::null_mut())
}

/// Everything to show, as JSON: this device, trusted devices (connected or not, both sides' switches) and
/// devices nearby. Free with `bridgey_string_free`. NULL for a stopped handle.
#[no_mangle]
pub extern "C" fn bridgey_snapshot(handle: u64) -> *mut c_char {
    std::panic::catch_unwind(|| client(handle).map(|c| give(c.snapshot().to_string())).unwrap_or(std::ptr::null_mut())).unwrap_or(std::ptr::null_mut())
}

/// # Safety
/// `name` is a NUL-terminated string valid for the call.
#[no_mangle]
pub unsafe extern "C" fn bridgey_set_device_name(handle: u64, name: *const c_char) -> i32 {
    guard(|| {
        let Some(c) = client(handle) else { return BRIDGEY_ERR_STOPPED };
        match arg(name) {
            Ok(Some(n)) if !n.trim().is_empty() => c.set_device_name(n).map(|_| BRIDGEY_OK).unwrap_or_else(code),
            _ => BRIDGEY_ERR_INVALID_ARGUMENT,
        }
    })
}

/// Lets another device pair with this one for `seconds` (0 turns it off; `UINT32_MAX` uses two minutes; at most
/// ten minutes). Call it when a pairing screen opens and closes too.
#[no_mangle]
pub extern "C" fn bridgey_allow_pairing(handle: u64, seconds: u32) -> i32 {
    guard(|| {
        let Some(c) = client(handle) else { return BRIDGEY_ERR_STOPPED };
        c.allow_pairing(if seconds == u32::MAX { ALLOW_DEFAULT } else { Duration::from_secs(u64::from(seconds)) });
        BRIDGEY_OK
    })
}

/// Pairs with a device, by its discovered ID, an IP address, or both. `*out_pairing` is the ID that pairing
/// events carry.
///
/// # Safety
/// `device_id` and `host` are NULL or NUL-terminated strings valid for the call; `out_pairing` is valid.
#[no_mangle]
pub unsafe extern "C" fn bridgey_pair(handle: u64, device_id: *const c_char, host: *const c_char, port: u16, out_pairing: *mut u64) -> i32 {
    guard(|| {
        let Some(c) = client(handle) else { return BRIDGEY_ERR_STOPPED };
        let (Ok(id), Ok(host)) = (arg(device_id), arg(host)) else { return BRIDGEY_ERR_INVALID_ARGUMENT };
        if out_pairing.is_null() {
            return BRIDGEY_ERR_INVALID_ARGUMENT;
        }
        match c.pair(id, host, port) {
            Ok(p) => {
                *out_pairing = p;
                BRIDGEY_OK
            }
            Err(e) => code(e),
        }
    })
}

/// The person's answer to the code: 1 it matches (pair), 0 it does not (cancel).
