/// Copies `len` bytes into the buffer a storage `load` callback was given.
///
/// # Safety
/// `buffer` is the pointer the callback received; `data` points to `len` bytes.
#[no_mangle]
pub unsafe extern "C" fn bridgey_buffer_set(buffer: *mut BridgeyBuffer, data: *const u8, len: usize) -> i32 {
    if buffer.is_null() || (data.is_null() && len > 0) {
        return BRIDGEY_ERR_INVALID_ARGUMENT;
    }
    let bytes = if len == 0 { Vec::new() } else { std::slice::from_raw_parts(data, len).to_vec() };
    (*buffer).data = Some(bytes);
    BRIDGEY_OK
}
